// 1. 元数据定义 - 页面描述
{
  "page": {
    "title": "用户管理",
    "components": [
      {
        "type": "SearchForm",
        "fields": [
          { "name": "username", "label": "用户名", "type": "input" },
          { "name": "status", "label": "状态", "type": "select",
            "options": [{"label":"启用","value":1},{"label":"禁用","value":0}] }
        ]
      },
      {
        "type": "DataTable",
        "entity": "user",
        "columns": [
          { "field": "username", "title": "用户名" },
          { "field": "email", "title": "邮箱" },
          { "field": "status", "title": "状态", "type": "tag" }
        ],
        "actions": ["add", "edit", "delete"]
      }
    ]
  }
}

// 2. 运行时引擎 - 组件渲染
@Component
public class ComponentRenderer {
    private final Map<String, ComponentHandler> handlers;

    public String render(ComponentMeta meta, Map<String, Object> data) {
        ComponentHandler handler = handlers.get(meta.getType());
        if (handler == null) {
            throw new UnsupportedComponentException(meta.getType());
        }
        return handler.render(meta, data);
    }
}

// 3. 动态实体服务
@Service
public class DynamicEntityService {
    @Autowired
    private EntityMetaMapper entityMetaMapper;

    // 创建动态实体
    public void createEntity(EntityMeta meta) {
        // 保存元数据
        entityMetaMapper.save(meta);
        // 动态建表（可选，或使用JSON存储）
        if (meta.getStorageType() == StorageType.TABLE) {
            dynamicTableService.createTable(meta);
        }
    }

    // 查询动态实体
    public Map<String, Object> findById(String entityName, Long id) {
        EntityMeta meta = entityMetaMapper.findByName(entityName);
        if (meta.getStorageType() == StorageType.TABLE) {
            return dynamicTableService.findById(meta.getTableName(), id);
        } else {
            return jsonStoreService.findById(entityName, id);
        }
    }

    // 保存动态实体
    public void save(String entityName, Map<String, Object> data) {
        EntityMeta meta = entityMetaMapper.findByName(entityName);
        // 校验字段类型
        validateData(meta, data);
        if (meta.getStorageType() == StorageType.TABLE) {
            dynamicTableService.save(meta.getTableName(), data);
        } else {
            jsonStoreService.save(entityName, data);
        }
    }
}

// 4. 组件注册
@Component
public class ComponentRegistry {
    private final Map<String, ComponentHandler> registry = new HashMap<>();

    @PostConstruct
    public void init() {
        // 注册内置组件
        registry.put("input", new InputComponentHandler());
        registry.put("select", new SelectComponentHandler());
        registry.put("table", new TableComponentHandler());
        registry.put("form", new FormComponentHandler());
    }

    public void register(String type, ComponentHandler handler) {
        registry.put(type, handler);
    }
}
